package com.paymentalarm.app;

import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class MainActivity extends Activity {
 LinearLayout root; int pad=18;
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setPadding(0,10,0,10);return t;}
 EditText field(String hint,String value){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(value);root.addView(e);return e;}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
 void msg(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("OK",null).show();}
 @Override public void onCreate(Bundle b){super.onCreate(b);permissions();home();}
 void permissions(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},5);}
 void home(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(pad,pad,pad,pad);scroll.addView(root);setContentView(scroll);root.addView(label("PAYMENT ALARM",27));root.addView(label("Local reminders • no subscription",14));
 AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())btn("ALLOW EXACT ALARMS (required)",()->startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName()))));
 if(Build.VERSION.SDK_INT>=34)btn("CHECK FULL-SCREEN ALARM PERMISSION",()->{Intent i=new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName()));try{startActivity(i);}catch(Exception e){msg("Find Special app access > Full screen intents in Settings.");}});
 btn("+ ADD PAYMENT ALARM",()->editor(null));JSONArray a=AlarmStore.all(this);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;root.addView(label("────────────",13));root.addView(label(x.optString("name")+"  RM "+x.optString("amount")+"\n"+(x.optString("mode").equals("once")?x.optString("date"):"Monthly: "+x.optString("days"))+String.format(Locale.US,"  %02d:%02d",x.optInt("hour"),x.optInt("minute")),17));btn("EDIT",()->editor(x));btn("DELETE",()->new AlertDialog.Builder(this).setMessage("Delete this alarm?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{AlarmStore.remove(this,x.optInt("id"));home();}).show());}
 btn("TEST IN 2 MINUTES",()->{Calendar c=Calendar.getInstance();c.add(Calendar.MINUTE,2);JSONObject x=new JSONObject();try{x.put("id",(int)(System.currentTimeMillis()%1000000000));x.put("name","TEST PAYMENT ALARM");x.put("amount","3000");x.put("note","Test: press STOP to silence");x.put("mode","once");x.put("date",String.format(Locale.US,"%04d-%02d-%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH)));x.put("hour",c.get(Calendar.HOUR_OF_DAY));x.put("minute",c.get(Calendar.MINUTE));x.put("enabled",true);AlarmStore.put(this,x);home();msg("Lock the screen. Alarm should ring at the scheduled minute.");}catch(Exception e){msg(e.toString());}});
 }
 void editor(JSONObject old){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(pad,pad,pad,pad);scroll.addView(root);setContentView(scroll);root.addView(label("PAYMENT DETAILS",24));EditText name=field("Payee / title",old==null?"ABC Supplier":old.optString("name"));EditText amount=field("Amount RM",old==null?"3000":old.optString("amount"));EditText note=field("Notes",old==null?"Payment due":old.optString("note"));
 root.addView(label("Repeat type",17));Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Monthly","One time"}));mode.setSelection(old!=null&&old.optString("mode").equals("once")?1:0);root.addView(mode);EditText days=field("Monthly dates, e.g. 5,6,7",old==null?"5,6,7":old.optString("days","5,6,7"));EditText date=field("One-time date YYYY-MM-DD",old==null?new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()):old.optString("date"));date.setFocusable(false);date.setOnClickListener(v->{Calendar c=Calendar.getInstance();new DatePickerDialog(this,(picker,y,m,d)->date.setText(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)),c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();});
 root.addView(label("Alarm time",17));TimePicker time=new TimePicker(this);time.setIs24HourView(true);time.setHour(old==null?9:old.optInt("hour"));time.setMinute(old==null?0:old.optInt("minute"));root.addView(time);
 btn("SAVE ALARM",()->{try{JSONObject x=new JSONObject();x.put("id",old==null?(int)(System.currentTimeMillis()%1000000000):old.optInt("id"));x.put("name",name.getText().toString().trim());x.put("amount",amount.getText().toString().trim());x.put("note",note.getText().toString().trim());x.put("mode",mode.getSelectedItemPosition()==0?"monthly":"once");x.put("days",days.getText().toString());x.put("date",date.getText().toString());x.put("hour",time.getHour());x.put("minute",time.getMinute());x.put("enabled",true);if(x.optString("name").isEmpty()||AlarmStore.next(x)<0){msg("Check title and future date / monthly dates.");return;}AlarmStore.put(this,x);home();}catch(Exception e){msg(e.toString());}});btn("CANCEL",this::home);
 }
 @Override public void onBackPressed(){home();}
 @Override protected void onResume(){super.onResume();AlarmStore.rescheduleAll(this);}
}
